#!/usr/bin/env python3
"""Package Collie's shared Flexscript engine in an Android application.

Python runs only on the build machine. The APK contains Java, a small C host,
and the existing Flexscript compiler/interpreter/provider/FlexDB compiled to ARM64.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import zipfile

ROOT = Path(__file__).resolve().parents[3]
HERE = Path(__file__).resolve().parent
TOKEN = re.compile(r'"(?:\\.|[^"\\])*"|//[^\n]*|[A-Za-z_]\w*|\s+|.', re.S)


def flatten(entries, transformed=None):
    """Preserve source bodies; only reorder module globals and remove imports."""
    seen, declarations, functions = set(), [], []
    for entry in entries:
        def visit(path):
            path = path.resolve()
            if path in seen:
                return
            assert path.is_relative_to(ROOT), path
            seen.add(path)
            text = (transformed or {}).get(path, path.read_text())
            imports = list(re.finditer(r'(?m)^\s*import\s+"([^"]+)"\s*;', text))
            for match in imports:
                visit(path.parent / match[1])
            text = re.sub(r'(?m)^\s*(?:import|extend)\s+"([^"]+)"\s*;', '', text)
            tokens = list(TOKEN.finditer(text))
            begin, level, function = 0, 0, False
            for token in tokens:
                word = token[0]
                if word.startswith('"') or word.startswith('//'):
                    continue
                if level == 0 and word in ('fn', 'view'):
                    function = True
                if word == '{':
                    level += 1
                elif word == '}':
                    level -= 1
                    if level == 0 and function:
                        functions.append(text[begin:token.end()])
                        begin, function = token.end(), False
                elif word == ';' and level == 0:
                    declarations.append(text[begin:token.end()])
                    begin = token.end()
            assert level == 0 and not function, path
        visit(entry)
    return '\n'.join(declarations), '\n'.join(functions)


def generate(out, compiler):
    # Run the shared view compiler on a small, normally imported UI program.
    # Exported modules are already validated by the same ordinary compiler;
    # flattening only adapts their host ABI, as for all other engine modules.
    ui_entry = out / 'ui-entry.flex'
    ui_entry.write_text('import '+json.dumps(str(ROOT/'apps/collie/ui/app.flex'))+';\n'
                        'extend '+json.dumps(str(ROOT/'libs/ui/syntax.flex'))+' with "source";\n'
                        'fn main(){return 0;}\n')
    generated = subprocess.run([str(compiler.resolve()), str(ui_entry), '-o', str(out/'ui-check')],
                               cwd=ROOT, capture_output=True)
    transformed = {}
    at = 0
    diagnostics = []
    # Length-prefixed UTF-8 modules avoid re-escaping/scanning generated source
    # in the bounded compile-time VM. No screen/compiler output is re-parsed by
    # an unrelated DSL implementation on the build host.
    while at < len(generated.stderr):
        end = generated.stderr.find(b'\n', at)
        if end < 0: end = len(generated.stderr)
        line = generated.stderr[at:end]
        at = end + 1
        if line.startswith(b'FLEXSCRIPT_UI_MODULE '):
            path_size, source_size = map(int, line.split()[1:])
            assert 0 < path_size < 16384 and 0 <= source_size < 1048576
            path = Path(generated.stderr[at:at+path_size].decode()).resolve()
            at += path_size
            assert path.is_relative_to(ROOT) and at+source_size <= len(generated.stderr)
            transformed[path] = generated.stderr[at:at+source_size].decode()
            at += source_size
            assert generated.stderr[at:at+1] == b'\n'
            at += 1
        else:
            diagnostics.append(line.decode(errors='replace'))
    if generated.returncode:
        raise RuntimeError('\n'.join(diagnostics))
    for line in diagnostics:
        if line: print(line)
    assert ROOT/'apps/collie/ui/app.flex' in transformed, 'UI compiler did not export the screen'
    declarations, functions = flatten([
        ROOT / 'compiler/main.flex',
        ROOT / 'apps/collie/adapters/linux.flex',
        ROOT / 'apps/collie/providers/codex.flex',
        ROOT / 'apps/collie/core/scheduler.flex',
        ROOT / 'apps/collie/core/checkpoint.flex',
        ROOT / 'apps/collie/core/recall.flex',
        ROOT / 'apps/collie/core/hardware.flex',
        ROOT / 'apps/collie/providers/stream.flex',
        ROOT / 'apps/collie/providers/images.flex',
    ], transformed)
    # Keep the original compiler and VM source shared. Only trusted HOST calls
    # change ABI; strings containing model instructions/guest source stay intact.
    names = {'alloc': 'ca_alloc', 'syscall': 'ca_host_syscall', 'main': 'ca_cli_main'}
    arities = {'ffi_open': 1, 'ffi_symbol': 2, 'ffi_call': 7,
               'ffi_call_i32': 7, 'ffi_call_u32': 7}
    names.update({name: 'ca_disabled_' + name for name in arities})
    def rewrite(text):
        return ''.join(names.get(t[0], t[0]) if re.fullmatch(r'[A-Za-z_]\w*', t[0])
                       else t[0] for t in TOKEN.finditer(text))
    declarations, functions = rewrite(declarations), rewrite(functions)
    functions = re.sub(r'(\bfn next\(\)\s*\{)', r'\1ca_compile_tick();', functions)
    functions = functions.replace('vm_execute(main_index);', 'cv_execute(main_index);')
    globals_ = re.findall(r'\bglobal\s+([A-Za-z_]\w*)\s*=\s*([^;]+);', declarations)
    assert globals_ and len(globals_) == sum(t[0] == 'global' for t in TOKEN.finditer(declarations)), 'unsupported global declaration'
    stubs = '\n'.join('fn ca_disabled_' + name + '(' +
                      ','.join('a'+str(i) for i in range(count)) + '){return 0;}'
                      for name, count in arities.items())
    # Engine globals also reset between native calls, including after a failed
    # compilation. All per-call mappings belong to the bounded native arena.
    extra_globals, extra_functions = flatten([HERE / 'engine.flex'])
    assert not (HERE / 'engine.flex').read_text().lstrip().startswith('import'), 'engine must use the shared flattened modules'
    globals_ += re.findall(r'\bglobal\s+([A-Za-z_]\w*)\s*=\s*([^;]+);', extra_globals)
    reset = 'fn ca_reset_globals(){\n' + '\n'.join(f'{n}={v};' for n,v in globals_) + '\n}\n'
    guest = (HERE / 'guest-files.flex').read_text() + '\n' + (ROOT/'apps/collie/guest/workers.flex').read_text() + '\n' + (ROOT/'apps/collie/guest/memory.flex').read_text() + '\n' + (ROOT/'apps/collie/guest/hardware.flex').read_text()
    guest += '\n' + (ROOT/'apps/collie/guest/usb-serial.flex').read_text() + '\n' + (ROOT/'apps/collie/guest/nfc.flex').read_text() + '\n' + (ROOT/'apps/collie/guest/uwb.flex').read_text()
    embedded = 'fn ca_guest_extra(){return '+json.dumps(guest, ensure_ascii=False)+';}\n'
    signatures=re.findall(r'^fn\s+(\w+)\(([^)]*)\)',(ROOT/'apps/collie/guest/hardware.flex').read_text(),re.M)
    serial_api={'serial_ports','serial_port','serial_open','serial_configure','serial_lines','serial_break','serial_read','serial_write','serial_status','serial_info','serial_close'}
    signatures += [(name,params) for name,params in re.findall(r'^fn\s+(\w+)\(([^)]*)\)',(ROOT/'apps/collie/guest/usb-serial.flex').read_text(),re.M) if name in serial_api]
    signatures += [(name,params) for name,params in re.findall(r'^fn\s+(\w+)\(([^)]*)\)',(ROOT/'apps/collie/guest/nfc.flex').read_text(),re.M) if name in {'ndef_record','ndef_encode','ndef_parse'}]
    signatures += re.findall(r'^fn\s+(\w+)\(([^)]*)\)',(ROOT/'apps/collie/guest/uwb.flex').read_text(),re.M)
    api="Android hardware API. All results are typed db values; device_field finds a map field.\n"+"\n".join(name+"("+params+")" for name,params in signatures)
    api += "\n\nSensor inventory returns a map with sensors/next/total; sensor_list_page uses offset and limit 1..32. next=-1 ends paging. Sensor/location measurements are db_real values with exact IEEE-754 bits in db_word. Subscriptions return handles for device_wait/device_close."
    api += "\nUSB inventory returns devices/next/total, limit 1..32. Configuration/interface pages use limit 1..8. Configuration/interface/endpoint IDs come from inventory. usb_open requires separate Android device approval. Claim an interface before endpoint transfers. Control and endpoint transfers use 1..8000 ms timeouts and at most 32768 bytes. IN requires request/endpoint direction bit 128; OUT requires it clear. Reads return blobs, writes return actual byte counts."
    api += "\nUSB serial: choose a port from serial_ports(id), then serial_open(id,port,force 0/1). serial_configure uses baud 50..3000000, data bits 5..8, parity 0 none/1 odd/2 even/3 mark/4 space, stop 0 one/1 one-and-a-half/2 two (one-and-a-half requires 5 data bits). Open defaults to 9600 8N1, DTR/RTS on and no flow control. Drivers cdc/ftdi/cp210x/ch34x run in Flexscript. serial_read/write use typed state, not a device handle; reads buffer packet remainders and writes may be partial. Use serial_close. Reopen after process restart/revocation/disconnect; saving state cannot preserve OS ownership."
    api += "\nKeystore: key_generate uses kind ec_p256/rsa2048/hmac_sha256/aes256 and backing any/hardware/strongbox. Aliases are workspace-scoped, 1..64 letters/digits/dot/underscore/hyphen; existing aliases cannot be overwritten. key_info reports actual Android security_level. key_sign/verify use SHA-256 and accept db_text/db_blob; verification signatures max 1024 bytes. key_public exports X.509 SPKI only; secret/private bytes cannot be exported. AES-only key_encrypt returns nonce/ciphertext blobs; key_decrypt requires the same authenticated additional data. Plaintext+aad max 32752 bytes, 12-byte nonce, 16-byte GCM tag. A new nonce is generated by Android for each encryption. Malformed signatures return false; authentication failures return an error. Keys persist across VM programs/restarts until key_delete. These keys do not require biometrics."
    api += "\nAudio: audio_devices returns devices/next/total, page limit 1..16. Device IDs come from inventory, or use default. Open PCM streams with rate 8000..192000 and channels 1 or 2; Android may reject unsupported formats. Encoding is signed PCM16 little-endian. Input needs microphone permission and a visible Collie activity; hiding Collie closes capture. device_read returns complete PCM frames, device_write accepts complete frames and may return a partial byte count. audio_control supports start/pause and playback-only flush while paused; audio_volume is per-stream 0..1000. audio_route selects a preferred device; device_info reports actual routed device, format and timestamps. Android may choose a different route."
    api += "\nMIDI: midi_list and midi_ports return devices or ports plus next/total, page limit 1..32. midi_open returns a device; midi_port_open(device,direction,number) uses send for a device input or receive for a device output. Read receive-port message/flush events with device_wait; message fields are data blob and timestamp_ns. midi_send and device_write return bytes sent; timestamp 0 is immediate, future timestamps are System.nanoTime-based and at most 60 seconds ahead. midi_flush sends a flush. MIDI byte and UMP devices are distinguished by transport/protocol; UMP sends must contain complete 32-bit words. Close ports/devices with device_close; closing a device closes its ports. MIDI watch handles report add/remove/status events. midi_bluetooth_open opens a known uppercase Bluetooth MAC through Android BLE-MIDI, asking for Nearby devices permission first; it does not scan or enable the radio."
    api += "\nDNS-SD: nsd_browse(type,network) and nsd_register(name,type,port,attributes,network) return resources. Use service types like _http._tcp.; selected-network support requires API33+. TXT advertising attributes are [key,text] pairs, each record max255 bytes and total1300; encode arbitrary binary as base64 text. Resolve/update attributes arrive as [key,blob] pairs. Use device_wait for started/found/lost/registered/updated/error events. Found events have id and service; service IDs belong to that browser only. nsd_services pages services/next/total (1..32); nsd_resolve returns name/type/port/network/addresses/attributes. nsd_watch_service returns an update resource on API34+. Close browser/registration/watch handles when finished. Use a LAN network, not a cellular-only connection."
    api += "\nVPN: vpn_open(name,addresses,routes,dns,mtu,apps,network) provides RAW IP packet transport, not encryption or peer discovery. It requires separate Collie VPN permission and Android system approval, starts while Collie is visible, and runs with a foreground service/Disconnect notification. Addresses/routes are lists of [numeric IPv4-or-IPv6,prefix_length]; routes must have zero host bits. DNS is a list of numeric addresses. MTU 576..32768 (IPv6 min1280). Apps [] means Collie only, [*] means all apps, [!package,...] excludes those packages; otherwise list allowed package names. Underlying network must be non-VPN. Only one Collie tunnel can be active. device_read must supply a limit at least MTU; device_write injects one complete packet. vpn_protect(tun,socket) excludes an owned TCP/UDP/listener transport socket from VPN routing. For TCP, net_tcp_open(network), protect, then net_tcp_dial(handle,host,port,timeout) before reads/writes. vpn_underlying changes the physical network; vpn_status reports prepared/active/owned/starting. The model's default connection uses a physical network outside Collie's own tunnel. Closing the handle/owner conversation or revoking Android VPN stops the interface; handles do not survive process restart."
    api += "\nCellular diagnostics: cellular_subscriptions(offset,limit 1..16) returns subscriptions/next/total and default/default_data/default_voice IDs. Use -1 for the default subscription, or an active id from inventory. cellular_info returns SIM/radio/operator and cached signal measurements; cellular_watch emits signal/data callbacks. cellular_watch_subscriptions emits ready/subscriptions_changed; enumerate again after changes. These calls ask for cellular access and Android READ_PHONE_STATE on first use. No phone numbers, IMSI, IMEI or ICCID are exported. cellular_service and cellular_watch_service additionally need Collie Location, Android precise Location and the Location switch enabled. cellular_cells(subscription,refresh 0 cached/1 requested) returns a snapshot handle, never a cell array. Requested refresh needs API29+, emits cells or error through device_wait and may be rate limited by Android. cellular_cell_page(snapshot,offset,limit 1..8) returns cells/next/total/reported_total/truncated. Up to128 cells are retained; timestamps use elapsed realtime nanoseconds and unavailable metrics are db_null. Cell identities are location data: snapshot/info/events/pages require BOTH cellular and location grants, and revoking either closes resources. Close snapshots/watch handles; live OS subscriptions cannot be restored from VM checkpoints. No calls, SMS, SIM modification or raw modem controls are provided."
    api += "\nWi-Fi: wifi_info returns radio/state/support flags without connection identity; wifi_watch returns ready/state/scan_availability events. wifi_connection reads the primary Wi-Fi connection (Android-quoted SSID), not the model route. Scan/connection/request/hotspot require BOTH wifi and location grants; Android asks for precise Location, and Nearby Wi-Fi on API33+ request/hotspot calls. wifi_scan(refresh0 cached/1 request) returns a snapshot; requested scans emit scan or error and Android can throttle them. wifi_scan_page(snapshot,offset,limit1..16) returns access_points/next/total/reported_total/truncated, at most128 APs. Android scan timestamps are elapsed-realtime microseconds; updated=false means cached data. wifi_request(ssid,security,password,bssid,hidden,timeout_ms1000..120000) asks Android's own network picker for a local-only network; use an exact SSID, optional BSSID or empty string, hidden0/1, and open/owe/wpa2/wpa3 personal security. It returns a lease, not an immediate connection. device_wait gives available/link_changed/lost/unavailable and a network selector for existing net_* calls; this never rebinds the process or model. Empty passwords only for open/owe; personal passphrases8..63 printable ASCII. wifi_suggest(ssid,security,password,hidden,metered,autojoin) returns a scoped lease, adds one Android suggestion and emits accepted/approval status (approval API31+). Android chooses whether to connect and requires per-app user approval; accepted does not mean connected or approved. Suggestions are removed on close/revocation/conversation closure; an app-private recovery journal removes orphan suggestions after process death on next launch. Passwords are not returned by device_info/events. wifi_hotspot returns a local-only hotspot lease; wait for started/error, then wifi_hotspot_config(handle) explicitly returns its SSID/security/password. Hotspots have no internet/tethering. Closing a pending hotspot waits for Android's callback and immediately closes any late reservation (the SDK has no pending-request cancel). Close every lease/snapshot. Wi-Fi Direct uses the p2p_* functions below. Aware and RTT use the functions described below; capability rows distinguish implementation from actual device support."
    api += "\nWi-Fi Direct: p2p_open returns the sole active Collie P2P channel; it requires wifi+location, Android Nearby on API33+, precise Location and the Location switch, and starts while visible. All child handles share both grants. p2p_discover/stop_discovery control peer discovery; p2p_peers(channel,offset,limit1..16) returns peers/next/total/revision, max128 peers. IDs are channel-scoped and can expire on refresh. p2p_connect(channel,peer_id,wps,pin,owner_intent) accepts discovered peers only; wps=pbc/display uses empty PIN, keypad uses4/8 digits, owner_intent=-1 default or0..15. Action success means Android accepted the request; wait for connection/group events and query p2p_connection/group to confirm formation. p2p_cancel cancels this channel's pending connection. p2p_group_create uses platform defaults; p2p_group_create_config(channel,name,password,band) needs API29+, DIRECT-xx-name up to32 UTF-8 bytes, an8..63 ASCII passphrase and band0 auto/1 2.4GHz/2 5GHz, with persistent mode disabled. p2p_group_remove and p2p_group_credentials operate only on this channel's owned group; credentials additionally require being the local group owner. Metadata/events never include passphrases. An existing group is not silently replaced. p2p_group_attach explicitly permits group-interface data I/O on an existing/incoming group without claiming ownership, removal rights or credentials. p2p_dns_sd_publish, p2p_upnp_publish, p2p_dns_sd_browse, p2p_dns_sd_txt, p2p_upnp_browse and p2p_service_request create child advertisements/queries; use p2p_service_discover to start service discovery and read dns_service/dns_txt/upnp/service_response events on the parent. A type-specific DNS-SD browse requests PTR service records; use p2p_dns_sd_txt(channel,instance,type) to request TXT attributes separately. TXT is bounded [key,text] pairs, max255 bytes/record and1300 total. Raw queries are hexadecimal up to1024 bytes and protocol0..255; raw responses are blobs. Close child handles to remove their registrations. p2p_tcp_connect/listen/accept and p2p_udp_open/send/receive use the formed owned/explicitly-attached group's interface, bind its local address and restrict destinations to numeric unicast addresses in its subnet; they never rebind model/process routing. TCP uses device_read/write, UDP returns address/port/data/truncated. Port/timeout bounds match net_*; close sockets explicitly. Group loss closes child sockets; closing the parent closes all children and releases only owned SDK actions. Android27+ explicitly closes the SDK Channel; Android26 can only stop/remove owned operations before releasing Java references. Android callback timeouts close the channel to discard late results. No host object references or persistent live OS handles are serialized."
    api += "\nWi-Fi RTT: wifi_rtt_info reports support/availability/max_peers and supported burst limits; wifi_rtt_watch returns an availability subscription. wifi_rtt_range(scan,bssids,burst) uses an owned completed wifi_scan snapshot, a list of distinct BSSID texts, and burst0 for Android defaults (custom burst requires API31+). It requires wifi+location, Android precise Location/Nearby, Location enabled and a visible activity at start. Wait for a ranging event containing results with status/bssid and, only on success, distance_mm/stddev_mm/rssi_dbm/attempted/successful/timestamp_ms. Failures and the30-second deadline emit error events. Closing discards late callbacks; the public Android API cannot cancel the radio request."
    api += "\nWi-Fi Aware: aware_info reports actual support/availability/limits; aware_watch returns availability events. aware_open returns an attachment; wait for attached before publishing/subscribing. Discovery/data/ranging require wifi+location and Android Nearby/precise Location with Location on. Start attach/discovery/network/ranging while visible. aware_publish and aware_subscribe return discovery handles; wait for started. name is1..255 UTF-8 bytes (ASCII letters/digits/hyphen/period or non-ASCII); info is a db_blob/db_text; filters is a list of blobs (max32 entries,255 bytes each,4096 total including length bytes). Device-reported limits may be smaller. kind0/1 is unsolicited/solicited publish or passive/active subscribe. ttl0 means no expiry, otherwise seconds up to86400. publish ranging0/1 enables ranging; subscribe min_mm/max_mm=-1 disables each distance bound (ranging requires API28+). Matching service events carry peer, info, filters, optional distance_mm and truncation flags. aware_peers pages peers/total/next with limit1..16, max128 peers. IDs belong only to that discovery session and expire on service_lost or close. aware_send(discovery,peer,id,bytes) sends one bounded discovery frame: IDs start at0 and strictly increase, max32 pending acknowledgements. Read message_sent/message_failed events with id, and received message events with peer/data/truncated. Use a data path for larger payloads. The corresponding *_update function permits one pending update; read updated/update_failed/error before another."
    api += "\nAware data: aware_network(discovery,peer,security,key,cipher,port,protocol,timeout_ms) returns a network lease. security=open/passphrase/pmk, key is empty/8..63 valid UTF-8 bytes/32 binary bytes. cipher0 uses platform defaults; cipher1/2 selects a supported NCS_SK128/256 suite on API33+. Only a secured publisher may announce port1..65535 or protocol0..255; use port0/protocol-1 to omit metadata. PMK and port/protocol require API29+. timeout1000..120000. Read available/peer_info/lost/unavailable events, then device_info gives network and remote address/port/protocol. Use existing net_* functions with that network selector (separate network grant required); this never rebinds model/process traffic. Both peers must request compatible data paths. aware_rtt(discovery,peer_ids,burst) measures known peers with RTT; results use the same channel-scoped peer IDs. Parent/session loss, peer loss and revocation close owned data/ranging resources. Close child handles and attachments explicitly. No live SDK handles survive VM/process snapshots."
    api += "\nClassic Bluetooth: bt_info/bt_watch require Bluetooth access and Android CONNECT on API31+. bt_bonded pages saved devices (limit1..16); bt_device(address) opens an explicit uppercase/lowercase Bluetooth address as a handle without connecting. Device info reports cached name/type/bond/class; no local hardware MAC is exported. bt_request_enable and bt_request_discoverable(seconds1..300) use Android's own consent UI outside the VM lock; discoverability additionally asks for ADVERTISE/SCAN to request and inspect the mode. Adapter scan_mode/discovering are null until Android SCAN is granted; inventory alone does not request it. Discoverability is global and expires under Android control; closing a handle cannot cancel it through the public SDK. bt_bond(device) asks Android to begin pairing; use device_info and bond events to observe its result. Pairing confirmation stays with Android. bt_uuids(device,refresh0/1) returns cached UUIDs and optionally requests asynchronous SDP; wait for a uuids event. Unpairing and cancelling another app's pairing are not public adapter operations."
    api += "\nBluetooth discovery: bt_scan(duration_ms1000..30000) needs Bluetooth AND Location grants, Android CONNECT/SCAN/precise Location, and Location enabled. It returns a scan handle with started/found/finished events. bt_scan_page(scan,offset,limit1..16) returns devices/next/total/omitted, at most128 peers. Results include address/name/type/bond/class and RSSI. Android Classic discovery is global: a Collie scan refuses an already active discovery and cancels only after its own request was accepted; finish or close it before connecting. Finished handles retain a permission-gated snapshot. Revocation/close erases it."
    api += "\nRFCOMM: bt_rfcomm_listen(name,canonical_uuid,secure0/1) registers one Collie listener per UUID. bt_rfcomm_accept(listener,timeout_ms1..8000) returns an already connected socket. bt_rfcomm_connect(device,uuid,secure0/1,timeout_ms1000..120000) returns a PENDING socket; read connected/error via device_wait before byte I/O. Connections run asynchronously to permit Android pairing UI; max2 pending per app. Secure RFCOMM authenticates the peer; insecure mode omits authentication and peers may reject it. Use device_read/write with32768-byte bounds. A byte-read timeout closes that socket to prevent late reads from consuming future data; writes are capped at8 seconds and failure may have partial completion. Adapter/peer disconnection invalidates the endpoint. Closing a listener does not close accepted sockets; close those separately. All handles are scoped to the conversation and Bluetooth grant, and never survive process snapshots."
    api += "\nBLE discovery/legacy advertisements: ble_info reports actual controller capabilities; GATT client bindings are listed separately; the GATT server has separate functions. ble_scan(service,address,duration_ms,mode) needs Bluetooth AND Location, Android CONNECT/SCAN/precise Location and Location enabled. Start while visible. Empty service/address omit filters; canonical UUID matches either an advertised UUID list or service-data UUID, optionally AND the exact MAC. duration1000..30000, mode0/1/2=low-power/balanced/low-latency. Results via found events and ble_scan_page(scan,offset,limit1..16), at most128 address/SID records; raw AD data is a typed blob for Flexscript parsing. Metadata includes RSSI, monotonic timestamp, PHY, connectable/legacy/data_status, SID, TX power and periodic interval. Android may pause unfiltered scans while the screen is off. finished/error and overflow are real events, never synthetic peers. Close erases results. ble_advertise(service,service_data,manufacturer,manufacturer_data,connectable,power,mode,duration_ms) requires Bluetooth, Android CONNECT/ADVERTISE, and a visible start. Empty UUID omits it; with empty service_data it advertises a UUID list, otherwise service data. manufacturer-1 omits that field. Byte fields at most27 each, power0..3, mode0..2, connectable0/1, duration0 until close or1..180000ms. Legacy radio limit31 bytes includes headers and flags; oversize combinations return an actual Android error event. No device name/local MAC is automatically included. Wait for started/error; close/revocation/adapter-off stops the owned SDK callback. Extended/periodic advertising remain pending bindings."
    api += "\nBLE GATT client: ble_connect(address,timeout_ms,operation_timeout_ms) takes an explicit MAC without scanning or requiring Location; it needs Bluetooth/Android CONNECT and a visible start. Both deadlines1000..120000. It returns a pending connection; wait for connected/error. Live SDK connections and attribute IDs never survive VM/process snapshots. ble_gatt_discover(connection,id) is asynchronous; wait for services status0. All asynchronous IDs must strictly increase (0..2147483647) within a connection, with at most ONE pending request. IDs are consumed when a request begins, including SDK rejection. A timeout or mismatched callback closes that connection, and later callbacks are discarded. device_info shows last_request_id/pending_id/pending_operation/last_result so queue overflow is detectable without losing the latest completion.\nGATT attributes: ble_gatt_items(connection,parent,offset,limit1..16) pages services for empty parent, characteristics for a service ID, descriptors for a characteristic ID. IDs are opaque, connection-owned and invalidated on every discovery attempt or services_changed. At most4096 records are accepted. Rows contain id/parent/kind/uuid/revision and actual SDK properties/permissions/instance where available. Repeated UUIDs remain distinct. ble_gatt_read(connection,attribute,id) emits read with id/attribute/status/value (a blob only on successful actual value). ble_gatt_write(connection,attribute,bytes,kind,id) emits write status; at most512 bytes. kind1=no-response,2=acknowledged,4=signed; descriptors require2. No-response/signed bytes must fit negotiated MTU minus3/15. A no-response callback means SDK completion, not proof of peer delivery. API33+ uses value-copy read callbacks and byte-array write APIs; older Android uses compatibility SDK object values copied at callback entry.\nGATT subscriptions: ble_gatt_local_notify(connection,characteristic,enabled0/1) ONLY enables/disables Android routing. To subscribe remotely, Flexscript must separately write the discovered 00002902-0000-1000-8000-00805f9b34fb descriptor: bytes[1,0] notifications, [2,0] indications, [0,0] disable, using acknowledged descriptor writes. Wait for write status0. Notification events carry attribute/revision/value copied into the bounded queue. Never infer remote subscription from local routing alone. ble_gatt_mtu(connection,23..517,id), ble_gatt_rssi(connection,id), ble_gatt_phy_read(connection,id), ble_gatt_phy(connection,tx_mask1..7,rx_mask1..7,options0..2,id) are asynchronous; observe actual mtu/rssi/phy_read/phy status. PHY masks1/2/4 select1M/2M/Coded. The MTU starts as a conservative23-byte bound; mtu_observed becomes true only on an actual successful SDK callback. device_wait can return db_null on a poll timeout: check db_kind(event)==5 before comparing map text. Android14+ may negotiate517 for the first MTU request and ignore later requests: use reported actual MTU, not the requested number. ble_gatt_priority(connection,0..2) requests balanced/high/low-power; acceptance is not proof of actual parameters. Close connections explicitly. Service change during a pending request closes the connection; otherwise rediscover after services_changed. Reliable-write transactions and included-service links are pending."
    api += "\nBLE GATT server: ble_server_open(response_timeout_ms1000..25000) needs Bluetooth/Android CONNECT and a visible start, no Location or ADVERTISE. It opens an owned SDK server and returns ready. ble_server_add(server,uuid,type0primary/1secondary,definitions) returns a pending service ID; wait for service_added status0 before advertising it. One registration at a time,15-second registration deadline. definitions is a list of [canonical_uuid,properties0..255,permissions,descriptors]; descriptors are [canonical_uuid,permissions]. Use ble_define_characteristic/ble_define_descriptor on db_list values to construct them. Characteristic properties: BROADCAST1,READ2,WRITE_NO_RESPONSE4,WRITE8,NOTIFY16,INDICATE32,SIGNED64,EXTENDED128. Permission flags read1/plain,2/encrypted,4/MITM; write16/plain,32/encrypted,64/MITM,128/signed,256/signedMITM. Max32 services,128 characteristics per addition,16 descriptors each,4096 attributes. SDK encryption permissions are enforced by Android. ble_server_items(server,parent,offset,limit1..16) lists services for empty parent or children of a service/characteristic. Rows expose id/parent/kind/uuid/active/properties/permissions. Duplicate UUIDs remain distinct local IDs; wait for active=true. ble_server_remove removes a service and invalidates all descendants; finish pending requests/operations first.\nServer peers and ATT: ble_server_peers pages up to32 connected opaque peer IDs with address/MTU/state. Android callbacks create peers; no scanning occurs. request events contain kind=read/write/execute, peer, attribute (null for execute), offset, prepared, response_needed, execute and actual value blob where present. Requests needing a response carry an opaque token; no-response write commands have token=null and must not be answered. ble_server_requests(server,offset,limit1..16) pages the live unanswered requests so queue overflow does not erase them. ble_server_respond(server,token,status0..255,offset0..512,bytes) calls the actual SDK response method, max512 bytes. A token is scoped to its server and consumed on a response attempt; expired/disconnected/answered tokens cannot be replayed. No values are automatically stored or read from SDK objects. Requests need running VM code to answer them: use bounded programs and persist application/transaction state in FlexDB. Progress checkpoints retain the total execution budget and are not an unlimited server loop. Flexscript owns value slicing, authorization, CCCD storage, and prepared-write buffers: echo accepted prepare-write offset/data, then atomically commit or discard on execute/cancel. Respond with proper ATT errors rather than inventing success.\nUnanswered server requests expire at the configured deadline and receive ATT Unlikely Error14; request_expired reports whether Android accepted that response. Invalid lengths/resource exhaustion are rejected with real length/resource ATT errors. A failed SDK response closes the registration. ble_server_notify(server,peer,characteristic,bytes,confirm0/1,id) starts a notification/indication, max512 bytes and peer MTU minus3. Declare NOTIFY16/INDICATE32 properties. Enabling a CCCD in Flexscript and choosing which peers receive updates is VM policy; the SDK does not do this automatically. Wait for notification_sent with peer/id/status/attribute/confirm; a notification callback alone is not proof of peer delivery. One outgoing notify/PHY operation per peer, IDs strictly increasing; peer metadata retains pending/last completion. ble_server_phy_read and ble_server_phy use actual SDK PHY callbacks. Timeout or disconnect during an outgoing operation closes the entire SDK registration to prevent ambiguous late callbacks (the Android notification callback carries only a device, no attribute/request ID). ble_server_disconnect requests disconnection of an owned peer. Close/revocation/adapter-off releases services, requests, peers and SDK resources. Advertising is a separately owned ble_advertise handle; close it too. Outbound server-initiated connect, included-service links and application-managed reliable-write helpers remain pending."
    api += "\nClassic HID device (Android9+): hid_open(name,description,provider,subclass,descriptor,incoming_qos,outgoing_qos,timeout_ms) requires Bluetooth/Android CONNECT and a visible app, without Location/SCAN/ADVERTISE. Metadata fields each1..50 UTF-8 bytes without NUL; subclass0..255; descriptor is a raw1..2048-byte blob. The descriptor and all report formats are your Flexscript protocol. QoS is an empty db_list() for SDK defaults, or hid_qos(service0..2,rate,bucket,peak,latency,variation); fields accept unsigned32-bit words or -1 for MAX. timeout1000..25000 applies to registration, connection state and unanswered controls. Wait for registered/error; the return value is only a pending handle. Android allows ONE registered HID app system-wide, temporarily disables its HID host profile and automatically unregisters background apps. Closing/background/revocation unregisters Collie's endpoint; wait for confirmed teardown before a new registration. A cleanup_unconfirmed event leaves new registration blocked until SDK confirmation or app restart. SDK resources never survive a VM/process snapshot.\nHID peers: pair the explicit bt_device with Android first (bt_bond and Android's pairing UI), then hid_connect(endpoint,device_handle) returns a pending owned peer ID. Observe connected/disconnected/connection_state; only real SDK connected callbacks allow reports. hid_peers(endpoint,offset,limit1..8) exposes owned IDs, address, SDK state0/1/2/3 and protocol0boot/1report. HID connected events can also arrive from a paired incoming host. hid_send(endpoint,peer,report_id0..255,bytes) sends an input report (bytes exclude the report ID); max510 bytes with a nonzero report ID, or511 with ID0. These bounds include the header/ID inside Android16's default512-byte HID MTU; the public proxy does not expose a negotiated peer MTU, so delivery still depends on actual peer/SDK limits. Success means SDK command acceptance, never delivery proof. hid_disconnect requests actual disconnection; use the resulting callback. Peer IDs expire on disconnect.\nHID controls: request events have kind=get_report/set_report, peer, report_type1input/2output/3feature, report_id, buffer_size, raw value/null and an owned opaque token. hid_requests(endpoint,offset,limit1..8) snapshots unanswered controls independently of event overflow. Answer GET_REPORT with hid_reply(endpoint,token,bytes), excluding report ID. For SET_REPORT, store/validate value in Flexscript then hid_error(endpoint,token,0) to acknowledge. Reject controls with hid_error codes1notReady,2invalidReportId,3unsupported,4invalidParameter,14unknown. Tokens are single-use and endpoint/peer-owned; invalid arguments do not consume them. One control transaction per peer because the SDK exposes no transaction IDs. An overlapping request or unanswered deadline closes the registration to discard ambiguous late replies. output_report events carry interrupt-channel output bytes and have no response token. protocol events report Android-acknowledged boot/report changes; adapt your report encoding in Flexscript. virtual_cable_unplug is a received host event; Android then disconnects. No public SDK unplug operation is exposed. Close the HID endpoint explicitly; a foreground service is not created automatically."
    api += "\nNFC reader: nfc_info/nfc_watch query actual NFC state and metadata; this is a separate nfc grant, not Bluetooth/Location. nfc_reader(flags,presence_delay_ms10..5000) requires a visible Activity and enabled NFC. Flags combine technology1A/2B/4F/8V/16barcode, optionally128 skipNdef/256 noSound. One reader mode per Collie app; it temporarily disables card-emulation while foreground. reader_requested means the SDK request was made, not proof of RF discovery. Actual tag events and nfc_tags(reader,offset,limit1..16) carry owned opaque IDs, UID blobs and SDK technologies; snapshots are limited to16, with omission counts. nfc_tag_info and nfc_cached_ndef use reader/tag IDs. Cached NDEF reflects discovery, not a fresh RF read. nfc_connect(reader,tag,technology) opens one SDK technology per tag; names NfcA/B/F/V, IsoDep, Ndef, NdefFormatable, MifareClassic/Ultralight or NfcBarcode. SDK connections stay outside snapshots. device_info reports actual cached protocol metadata, SDK transceive limits and timeouts; cached tag properties do not automatically refresh after writes. NFC background/radio-off/reader-close invalidates children.\nNFC I/O: nfc_transceive(technology,bytes) passes raw technology commands/APDUs and returns actual bytes, bounded by both32768 and the SDK's maximum. No invented responses. nfc_timeout sets1..5000ms only where supported. nfc_mifare_auth(technology,sector,key6bytes,key_type0A/1B) uses Android's native authentication; keys are not logged. nfc_ndef_read/write operate on connected Ndef using raw encoded messages. nfc_ndef_read_only permanently locks a tag; nfc_ndef_format(technology,message,read_only0/1) uses NdefFormatable and may irreversibly lock it. Only call those when explicitly intended. nfc_ignore(reader,tag,debounce_ms0..60000) invalidates further use of that tag; tag_ignored is not proof of removal. tag_removed is emitted only on the SDK's actual removal callback. TagLost/stale-cookie/IO errors invalidate affected resources; write completion may be uncertain.\nPortable NDEF: ndef_record(tnf0..5,type_blob,id_blob,payload_blob) returns a four-field typed list. ndef_encode(records) produces a canonical unchunked binary message up to32768 bytes, with correct short/long and ID fields. ndef_parse(blob) validates message flags/lengths and reassembles chunked payloads into the same list format. These functions run entirely in Flexscript; no host/DB access is needed. Binary NFC/APDU content and higher-level protocols remain your code.\nSecure elements: se_open(timeout_ms500..30000) needs secure_element and Android9+. Wait for actual connected/error, then se_readers(service,offset,limit1..16) enumerates SDK readers/presence with opaque service-owned IDs. Empty readers is a real valid result, not APDU proof. se_uicc(service,slot1based) requires Android11+. se_session(service,reader_id), se_channel(session,aid_blob,basic0logical/1basic,p2byte) return owned SDK objects. AID empty selects the default applet; otherwise5..16 bytes. Android/secure-element access rules enforce certificates, applet presence and command restrictions. access_denied/applet_not_found/channel_unavailable are real errors; they are not bypassed. device_info reports SDK service/session/channel state, ATR and SELECT response. se_select_response and se_select_next call the actual channel methods.\nOMAPI APDUs: se_transmit(channel,command_blob4..32768bytes) returns a map {id,value,total,next,status_word}; value is the first response page, including actual SW1/SW2. status_word is the card's raw status, not an invented success boolean. se_response(channel,id,offset,limit1..32768) fetches remaining bytes without replaying the APDU; IDs become stale on the next exchange. Full extended commands use se_command(channel,total4..65544), sequential se_command_write(channel,offset,bytes), then se_send(channel) once. Responses are bounded to65538 bytes. Interrupted/failed sends are never automatically replayed. Only one APDU may be in flight per channel. Closing clears staged commands and cached responses. SDK close/shutdown can wait for APDUs, so local handles invalidate immediately and SDK cleanup runs off the UI thread; a timed-out call invalidates its whole owned service and completion may remain uncertain until the vendor call returns. Bounds per service:16 sessions/32 channels, including pending cleanup; at most8 services per app. Each service owns its readers; shutdown never calls another conversation's SDK service. No root/system/SE access-control bypass is provided."
    api += "\nInput devices: input_devices(offset,limit1..16) returns actual Android device metadata and total/next; input_info(id), input_ranges(id,offset,limit1..16) and input_has_keys(id,key_codes1..128) query the SDK. IDs are transient Android integers; enumerate again after changes. These need the input grant. input_watch(device_id,mask,axes,history_limit) subscribes only to events delivered to Collie's own visible Activity, passively: it does not consume the UI event or observe other apps. Device-1 means all; mask bits1 touch,2 keys,4 generic mouse/joystick motion,8 device added/changed/removed. Request up to16 distinct motion axis codes0..63; include X0/Y1 and any pressure/stylus/gamepad axes wanted. history_limit0..8 adds bounded historical samples; history_omitted reports discarded older samples. Each motion sample has event/down timestamps in uptime milliseconds, source/device/action/buttons/meta/classification and pointers as [pointer_id,tool_type,axis_values] rows, in the requested axis order. Floating values are db_real bits. Historical rows retain the containing SDK event's action, not an invented independent dispatch. Up to32 pointers, with pointers_omitted. Key events copy actual key/scan/action/repeat/meta/unicode and optional characters, bounded to4096 UTF-16 units without splitting surrogate pairs; characters_truncated explicitly reports truncation. Software keyboards may commit text without KeyEvents; use normal text widgets for IME text. No input injection or global key capture API exists. Streams use bounded common event queues with overflow counts, close on background/revocation/conversation change, and selected-device streams close on removal. At most8 subscriptions per app. No separate Android runtime permission is required for observing the app's own delivered events."
    api += "\nSystem authentication: biometric_info(authenticators) queries Android availability and credential configuration without launching UI. authentication_status is the actual BiometricManager value, or null/status_known=false if unavailable; never infer authentication from feature flags, enrollment or availability. Authenticators are15 Class3/strong,255 Class2-or-better/weak,32768 device PIN/pattern/password, or biometric|credential (32783/33023). Optionally add65536 Identity Check on Android16+, whose policy remains under Android. biometric_auth(title,subtitle,description,authenticators,confirmation0/1,timeout_ms500..120000) requires the biometrics grant, Android9+ and a visible start. Title is nonempty, max200 UTF-16 units; subtitle400/description2000. On Android9 only default weak255 with confirmation1 is expressible; Android10 additionally supports weak|credential33023 and the confirmation hint. Unsupported strength selections are rejected rather than downgraded. Confirmation is an Android hint, not a promise that a modality needs another tap.\nAuthentication returns a pending owned handle. requested means the SDK call was made, not success or proof the prompt was displayed. Use device_wait for actual help/not_recognized/nonterminal events and authenticated/error terminal callbacks; device_info reports state, actual last_result, sdk_requested/sdk_terminal, late_success_rejected and cleanup_pending. late_success_rejected records an actual success callback that was refused after cancellation or expiry; it is not authentication. Only actual onAuthenticationSucceeded produces authenticated, with Android's raw authentication_type (null before Android11) and elapsed completion timestamp. Biometric templates, images, credential text, and crypto keys are never returned. This result is not a cryptographic attestation or a Keystore authorization token. Android owns the prompt, negative button, enrollment requirements and background cancellation. No enrollment or lock settings are changed by these functions.\nbiometric_cancel(handle) requests cancellation while keeping the handle observable (typed int1 if newly requested, int0 if already finishing/terminal, or error0 with db_error); cancellation_requested is not terminal confirmation. device_close invalidates the handle and cancels its SDK request. Conversation close/revocation/process destruction cancels owned requests; SDK resources are not snapshotted. A timeout reports failure and requests SDK cancellation. Late success after cancellation/timeout is not accepted. Only one Collie prompt may be pending, including cancellation awaiting a real terminal callback. Starting another returns busy until SDK completion; unconfirmed teardown is visible instead of silently replacing another conversation's prompt."
    api += "\nUWB public ranging (Android16+): uwb_info() returns {sdk,feature,public_ranging_api,snapshot} with an actual SDK capability snapshot, and uwb_watch() returns an owned observer whose capabilities events carry the actual snapshot. No Android RANGING runtime grant is needed for capabilities; both still require Collie UWB approval. Snapshot availability values are0 not-supported,1 user-disabled,2 regulatory-disabled,3 enabled,4 user-restrictions. Feature flags and enabled state do not prove any ranging measurement. hardware_capabilities reports unknown availability until a snapshot is queried, plus remaining8 observer and8 session slots; pending SDK cleanup counts toward those limits. SDK capability lists are bounded to256 values. On older Android, uwb_info reports public_ranging_api=false and older_binding_implemented=false; other UWB operations explicitly reject the unimplemented older binding.\nUse uwb_peer(uuid,session_id,config_id,local_address,peer_address,channel,preamble,rate,slot,key,sub_session_id,sub_key) to build one typed12-field record. UUID is canonical; IDs are unsigned32-bit values, except sub_session_id=-1 means unset. Addresses are binary db_blob values of2 or8 bytes. Keys are binary blobs up to32 bytes; an empty blob leaves the SDK key unset. The caller must choose matching peer security/profile/session parameters; nothing is negotiated, weakened or retried automatically. Profiles1..6 are Android16 UwbRangingParams constants, distinct from older Jetpack profile IDs. Channel and preamble are both explicit or both0 to leave them unset. Rate1normal/2infrequent/3frequent; slot1or2 milliseconds. Read actual supported values from the snapshot. These record constructors are pure computation and need no permission.\nuwb_options(angles0/1,measurement_limit0..65535,fusion0/1,notification0..3,near_cm,far_cm,open_timeout_ms500..120000) creates the session record. Notification0disabled/1enabled/2proximity-level/3proximity-edge; proximity values0..20000 and near<=far; limit0 means the SDK's unlimited setting. uwb_range(role,peers,options) requires UWB and first-use Android Nearby RANGING consent. Role1initiator accepts1..8 peers, role0responder exactly1. It returns a pending session; only actual SDK callbacks yield opened/started/ranging/stopped/open_failed/closed events. After a session has opened, an SDK onOpenFailed callback is exposed as operation_failed and does not pretend the existing session closed; wait for actual closed confirmation. opened is session setup, not measured distance. Ranging events contain peer UUID, technology0UWB, elapsed-realtime timestamp_ms, nullable distance_m/azimuth_degrees/elevation_degrees measurement objects {value(db_real),confidence0low/1medium/2high}, and nullable rssi_dbm. No measurements or callbacks are fabricated. Check db_kind before reading optional fields or comparing their text. Background policy remains with Android and actual device capabilities.\nAfter opened, uwb_add(handle,peer) adds an explicitly configured peer to an initiator (at most8 known UUIDs per session); uwb_remove(handle,uuid) requests removal, and uwb_interval(handle,skip0..255) requests interval skip-count reconfiguration. SDK method acceptance does not confirm a radio change; observe actual callbacks. Unknown peers and other workspaces are rejected. uwb_stop(handle) returns typed1 for a new stop request or typed0 when already stopping/terminal; keep observing until sdk_terminal. device_info reports state, role, known peer UUIDs and elapsed_realtime_ms (the same monotonic clock as measurement timestamps). Known peers are configured identities, not proof of connection. device_close invalidates locally and requests SDK stop. Pending cleanup retains its slot until an actual terminal callback, or confirmation that no radio request was made; cleanup_call_returned is distinct from sdk_terminal. Vendor errors are visible as cleanup_error, without pretending teardown succeeded. Startup deadlines and cancellation are bounded, copied events use the common bounded queue, and SDK objects never survive a VM/process snapshot. Each session uses an independent Android service cache because Android16 retains framework session records. SDK builder fixtures and emulator measurements do not establish physical UWB ranging.\n"
    api += "\nDocument folders: document_pick(ticket,writable0/1) asks the user to choose a folder through Android's picker after the separate documents first-use grant. Tickets use1..64 letters/digits/dot/underscore/hyphen and must be new for each selection. Reusing a ticket returns its saved grant or cancellation, never another picker. document_trees(offset,limit1..16) lists this workspace's durable selections including cancelled tickets and actual Android grant flags. document_forget(grant) removes this workspace's selection, closes its trees/streams and releases OS grant bits unused by other saved selections. No broad storage permission or raw URI/path input. Android may restrict root/Download/Android-data folders. document_tree_open(grant) returns a live tree with root token root. document_info and document_children(tree,node,offset,limit1..16) return actual provider name/mime_type/flags/nullable size/last_modified_ms; directory pages include documents/next/total/loading. Use only returned opaque document tokens with that same live tree. Up to8 trees globally and1024 known tokens per tree; reopen to traverse more. Handles/tokens expire across process restarts and close; saved grants survive. document_create(tree,parent,name,mime) creates a file or vnd.android.document/directory. document_rename and document_delete cannot mutate the selected root. Successful mutations invalidate prior non-root tokens and close streams; enumerate again. Operations may fail according to provider flags, offline state or revoked Android approval; SDK writes can have uncertain completion on timeout and are never replayed automatically. document_file_open(tree,node,mode) supports Android modes r,w,wt,wa,rw,rwt; w truncation is provider-dependent, wt/rwt explicitly truncate. Read-only selections cannot open writable streams. Use device_read(max32768bytes,timeout1..8000), device_write (actual partial byte count), document_seek(file,absolute_offset), device_info and device_close. EOF is db_null; nonseekable providers return unsupported_operation. Closing a tree closes children. documents denial cancels existing resources. document_copy/move/remove use the actual provider operations within the same tree and require its support; remove detaches a parent link, delete removes the document. Their successful mutations also expire old tokens. document_types(tree,node,mime_filter) returns up to64 advertised converted stream MIME types. document_typed_open(tree,node,concrete_mime) opens a read-only converted/virtual file stream; generic device_read honors the asset offset/declared length and EOF. Converted streams are not seekable through document_seek. Virtual data exists only if the provider implements that conversion; actual removable/cloud-provider checks remain pending."
    index="Android hardware function index. All results are typed db values. Detailed contracts: hardware_api_page(offset,limit1..32768) returns {text,total,next}; follow next until-1.\n"+"\n".join(name+"("+params+")" for name,params in signatures)
    assert len(index.encode())<=32768, 'Hardware function index needs pagination before it exceeds one VM value'
    embedded+='fn ca_hardware_index(){return '+json.dumps(index,ensure_ascii=False)+';}\n'
    embedded+='fn ca_hardware_api(){return '+json.dumps(api,ensure_ascii=False)+';}\n'

    source = out / 'engine-generated.flex'
    source.write_text(declarations+'\n'+extra_globals+'\n'+functions+'\n'+stubs+'\n'+
                      reset+embedded+extra_functions+'\nfn main(){return 0;}\n')
    # A small UI image has its own globals and allocator. Native UI evaluation
    # must never wait for the compiler/guest VM's process-wide engine lock.
    ui_globals, ui_functions = flatten([ROOT/'apps/collie/ui/app.flex'], transformed)
    ui_names = {'alloc':'uh_alloc', 'syscall':'uh_syscall'}
    ui_names.update({name:'uh_disabled_'+name for name in arities})
    def ui_rewrite(text):
        return ''.join(ui_names.get(t[0],t[0]) if re.fullmatch(r'[A-Za-z_]\w*',t[0]) else t[0]
                       for t in TOKEN.finditer(text))
    ui_globals, ui_functions = ui_rewrite(ui_globals), ui_rewrite(ui_functions)
    ui_variables = re.findall(r'\bglobal\s+([A-Za-z_]\w*)\s*=\s*([^;]+);',ui_globals)
    ui_reset = 'fn uh_reset(){'+''.join(f'{name}={value};' for name,value in ui_variables)+'return 0;}\n'
    ui_stubs = stubs.replace('ca_disabled_', 'uh_disabled_')
    ui_source = out/'ui-generated.flex'
    ui_source.write_text(ui_globals+'\nglobal uh_bridge=0;global uh_packet=0;\n'+ui_functions+'\n'+ui_stubs+'\n'+ui_reset+
        'fn uh_syscall(n,a,b,c,d,e,f){store64(uh_packet,a);store64(uh_packet+8,b);store64(uh_packet+16,c);store64(uh_packet+24,d);store64(uh_packet+32,e);store64(uh_packet+40,f);return ffi_call(uh_bridge,n,uh_packet,0,0,0,0); }\n'
        'fn uh_alloc(n){return uh_syscall(1000,n,0,0,0,0,0); }\n'
        'fn uh_entry(op,text,bridge,packet){uh_reset();uh_bridge=bridge;uh_packet=packet;let request=c_json(text);let result=0;if op==10{result=cu_permissions(request);}else{result=cu_ui_host(request);}return j_dump(result); }\n'
        'fn main(){return 0;}\n')
    return source,ui_source


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--compiler', type=Path, required=True)
    parser.add_argument('--out', type=Path, default=ROOT/'build/collie-android')
    parser.add_argument('--sdk', type=Path, default=Path(os.environ.get('ANDROID_HOME','/opt/android-sdk')))
    parser.add_argument('--java-home', type=Path)
    parser.add_argument('--native-only', action='store_true')
    parser.add_argument('--debug', action='store_true', help='Enable private ADB testing; development only')
    args = parser.parse_args()
    out = args.out.resolve()
    out.mkdir(parents=True, exist_ok=True)
    env = dict(os.environ)
    if args.java_home:
        env['JAVA_HOME'] = str(args.java_home.resolve())
        env['PATH'] = str(args.java_home.resolve()/'bin')+os.pathsep+env['PATH']
    def run(command):
        subprocess.run(list(map(str, command)), cwd=ROOT, env=env, check=True)
    source,ui_source = generate(out, args.compiler)
    run([args.compiler.resolve(), '--target','android-arm64',source,'-o',out/'engine.o'])
    flags = ['clang','--target=aarch64-linux-android26','-ffreestanding','-fPIC',
             '-fno-stack-protector','-fno-builtin','-fvisibility=hidden',
             '-mgeneral-regs-only','-Wall','-Wextra','-Werror','-O2']
    run([args.compiler.resolve(), '--target','android-arm64',ui_source,'-o',out/'ui.o'])
    run([*flags,'-c',HERE/'ui-host.c','-o',out/'ui-host.o'])
    run([*flags,'-Dcollie_call=collie_ui_call','-c',HERE/'native-test.c','-o',out/'ui-test.o'])
    run(['ld.lld','-static','-e','_start',out/'ui-test.o',out/'ui-host.o',out/'ui.o','-o',out/'ui-native-test'])
    run(['ld.lld','-shared','-Bsymbolic','-z','defs','-z','relro','-z','now','-z','noexecstack',
         '-z','max-page-size=16384','--hash-style=both','-soname','libcollie_ui.so',
         out/'ui-host.o',out/'ui.o','-o',out/'libcollie_ui.so'])
    run([*flags,'-c',HERE/'host.c','-o',out/'host.o'])
    run([*flags,'-c',HERE/'native-test.c','-o',out/'native-test.o'])
    run(['ld.lld','-static','-e','_start',out/'native-test.o',out/'host.o',
         out/'engine.o','-o',out/'native-test'])
    run(['ld.lld','-shared','-z','defs','-z','relro','-z','now','-z','noexecstack',
         '-z','max-page-size=16384','--hash-style=both','-soname','libcollie.so',
         out/'host.o',out/'engine.o','-o',out/'libcollie.so'])
    if args.native_only:
        print(out/'native-test')
        return
    sdk = args.sdk.resolve()
    tools = sdk/'build-tools/36.1.0'
    android = sdk/'platforms/android-36/android.jar'
    assert android.is_file(), android
    classes, dex = out/'classes', out/'dex'
    # Deleted platform classes must not survive incremental APK builds.
    for directory in (classes, dex):
        if directory.exists(): shutil.rmtree(directory)
        directory.mkdir()
    java = lambda name: shutil.which(name,path=env['PATH'])
    java_sources = sorted(HERE.glob('*.java'))
    if args.debug: java_sources += sorted((ROOT/'apps/collie/tests/android').glob('*.java'))
    run([java('javac'),'-source','8','-target','8','-classpath',android,
         '-d',classes,*java_sources])
    run([tools/'d8','--min-api','26','--lib',android,'--output',dex,*sorted(classes.rglob('*.class'))])
    manifest=out/'AndroidManifest.xml'
    manifest_text=(HERE/'AndroidManifest.xml').read_text().replace('android:debuggable="false"', 'android:debuggable="'+str(args.debug).lower()+'"')
    if args.debug:
        manifest_text=manifest_text.replace('</application>', '<service android:name=".MidiLoopbackFixture" android:exported="true" android:permission="android.permission.BIND_MIDI_DEVICE_SERVICE"><intent-filter><action android:name="android.media.midi.MidiDeviceService" /></intent-filter><meta-data android:name="android.media.midi.MidiDeviceService" android:resource="@xml/midi_loopback_fixture" /></service></application>')
    manifest.write_text(manifest_text)
    run([tools/'aapt2','compile','--dir',HERE/'res','-o',out/'resources.zip'])
    resources=[out/'resources.zip']
    if args.debug:
        run([tools/'aapt2','compile','--dir',ROOT/'apps/collie/tests/android/res','-o',out/'test-resources.zip'])
        resources.append(out/'test-resources.zip')
    run([tools/'aapt2','link','-I',android,'--manifest',manifest,*resources,
         '--version-code','1','--version-name','0.1.0','-o',out/'unsigned.apk'])
    with zipfile.ZipFile(out/'unsigned.apk','a',compression=zipfile.ZIP_STORED) as apk:
        apk.write(dex/'classes.dex','classes.dex')
        apk.write(out/'libcollie.so','lib/arm64-v8a/libcollie.so')
        apk.write(out/'libcollie_ui.so','lib/arm64-v8a/libcollie_ui.so')
    run([tools/'zipalign','-f','-P','16','4',out/'unsigned.apk',out/'aligned.apk'])
    key = out/'development.keystore'
    if not key.exists():
        run([java('keytool'),'-genkeypair','-noprompt','-keystore',key,
             '-storepass','android','-keypass','android','-alias','development',
             '-dname','CN=Collie Development','-keyalg','RSA','-keysize','2048','-validity','3650'])
    apk = out/'collie.apk'
    run([tools/'apksigner','sign','--ks',key,'--ks-key-alias','development',
         '--ks-pass','pass:android','--key-pass','pass:android','--out',apk,out/'aligned.apk'])
    run([tools/'apksigner','verify',apk])
    run([tools/'zipalign','-c','-P','16','4',apk])
    report = dict(apk=str(apk),sha256=hashlib.sha256(apk.read_bytes()).hexdigest(),
                  package='org.flexscript.collie',abi='arm64-v8a',debug=args.debug,
                  compiler=str(args.compiler.resolve()),engine='shared Flexscript frontend, checked interpreter, provider protocol and FlexDB')
    (out/'build.json').write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps(report,indent=2))


if __name__ == '__main__':
    main()
